     "summary": "9月全社会用电量8997亿千瓦时，同比增1.2%；一、二、三产业及工业用电分别增4.1%、1.7%、4.9%、1.8%，高技术制造业增4.6%，充换电与互联网数据服务用电增速达57.0%、35.4%；居民生活用电降6.0%，主因台风致降温需求减少。1—9月累计用电80734亿千瓦时，同比增3.9%。",
